"""Replace obsolete methods/results in the conference manuscript with measured 3 s variance results."""
import json
import pandas as pd

def revise(blocks,exp):
    blocks=list(blocks)
    results=pd.read_csv(exp/'results.csv');paired=pd.read_csv(exp/'paired_minutes.csv')
    raw=pd.read_csv(exp/'all_minutes.csv');audit=pd.read_csv(exp/'coverage_audit.csv')
    ranked=results[results.split=='validation_minutes'].sort_values(['balanced_accuracy','auc','model'],ascending=[False,False,True]).drop_duplicates('features').set_index('features')
    def test(name):
        model=ranked.loc[name,'model']
        return results[(results.features==name)&(results.model==model)&(results.split=='test_minutes')].iloc[0]
    csi,snr,fusion,rd,allrad=[test(n) for n in ['CSI','SNR','CSI+SNR','CSI+SNR+RD','CSI+radar all']]
    selected=json.loads((exp/'selection.json').read_text());win=test(selected['features'])
    counts=paired.groupby('split').size();nt=int(counts['test_minutes']);ne=int(win['empty']);no=int(win.occupied)
    rawauc=json.loads((exp/'raw_csi_auc.json').read_text());vauc=rawauc[0]['auc'];tauc=rawauc[1]['auc']
    med=paired.groupby('split').ra_mean.median()
    def replace(prefix,new):
        found=[i for i,(k,v) in enumerate(blocks) if isinstance(v,str) and v.startswith(prefix)]
        assert len(found)==1,(prefix,found)
        i=found[0];blocks[i]=(blocks[i][0],new)
    replace('<b>Abstract',f'<b>Abstract—</b>Room occupancy detection requires reliable recognition of moving and stationary occupants. This paper investigates lightweight fusion of WiFi channel state information (CSI) and radar using 1,523 labeled minute recordings. The CSI feature is the sum of coordinate variances of three consecutive one-second observations in a fixed two-dimensional principal-component space. Valid three-second window variances are aggregated by their median within each minute, without computing inter-dot path distances. The feature is fused with a radar signal-to-background proxy and range-Doppler, range-azimuth, range-elevation, and XY energy descriptors. Thirteen input configurations and two conventional classifiers are evaluated with chronological partitions and validation-selected thresholds. The three-second CSI feature is available for every labeled minute, including all 96 empty and 153 occupied test minutes. On the matched test cohort of {nt} minutes, CSI alone achieves {csi.balanced_accuracy*100:.1f}% balanced accuracy and {csi.auc:.3f} ROC AUC; CSI plus SNR gives {fusion.balanced_accuracy*100:.1f}% and {fusion.auc:.3f}, respectively. The overall validation-selected {selected["features"]} ({selected["model"]}) candidate achieves {win.balanced_accuracy*100:.1f}% test balanced accuracy. The study provides an auditable short-window variance baseline and characterizes the effects of radar representation and temporal distribution shift. Results remain exploratory because the evaluation recordings have been examined during development.')
    replace('This paper investigates these issues','This paper investigates these issues using an interpretable representation: the variance of consecutive CSI projections in a fixed two-dimensional PCA space. Three adjacent one-second observations define each window. The sum of the two coordinate variances is used as a scalar measure of local dispersion, with no cumulative distance calculation. This feature is combined with a radar SNR proxy and four radar-map representations. The contribution is an audited multimodal dataset description, a reproducible short-window feature pipeline, and a matched-cohort comparison of 26 candidates that reports coverage alongside classification quality.')
    replace('The study is exploratory.',f'The study is exploratory. The overall candidate is selected from validation results, not from the highest test score. In the revised experiment, {selected["features"]} ({selected["model"]}) is selected and reaches {win.balanced_accuracy*100:.1f}% test balanced accuracy. The shortened CSI window removes the severe minute-exclusion problem encountered with longer contiguous windows. It does not establish that every second is observed, or that the system generalizes to unseen rooms and participants.')
    replace('A CSI second is valid only',f'A CSI second is valid only when it contains at least five packets, spans at least 0.5 seconds, and has no packet or boundary gap greater than 0.5 seconds. Three consecutive valid one-second observations are required for each variance window, covering three contiguous one-second bins. Missing intervals are not interpolated. All 808 calibration, 274 training, 192 validation, and 249 test minutes contain at least one usable window. Requiring all radar inputs leaves {int(counts["train"])} training, {int(counts["validation_minutes"])} validation, and {nt} test minutes (Table I).')
    replace('Using a fixed basis is essential','Using a fixed basis makes coordinate variances comparable across windows and partitions. If axes and scaling were refitted independently per window, changes in the representation could be confused with changes in the signal. PCA does not guarantee occupancy relevance: its directions maximize variance in the fit population, which is strongly influenced by calibration recordings. The stored calibration-and-training basis is retained for this experiment.')
    replace('B. Twenty-second','B. Three-second projection variance')
    replace('For start second s, cumulative','For start second s, the three dots z(s), z(s+1), and z(s+2) summarize the bins [s,s+1), [s+1,s+2), and [s+2,s+3). Population variance is computed separately for each of the two coordinates (ddof = 0); the scalar feature is their sum, equivalently the trace of the population covariance matrix. The hop is one second, giving up to 58 windows per minute. No distances between consecutive dots are summed. The minute feature is the median of valid window variances, and the classifier receives log(1 + V<sub>m</sub>).')
    replace('L(s) =','V(s) = (1/3) sum<sub>j=0</sub><super>2</super> ||z<sub>s+j</sub> - z<sub>mean,s</sub>||<sub>2</sub>².  (4)')
    replace('L<sub>m</sub>','V<sub>m</sub> = median {V(s): all three bins are valid}.  (5)')
    replace('Path length measures','Here z<sub>mean,s</sub> is the mean of the three two-dimensional dots. The statistic measures local dispersion around that centroid and is invariant to permuting the three dots. A stationary set of identical dots has zero variance. Its units are squared PCA-coordinate units, not physical displacement. Signal gain, packet quality, and residual noise can still affect it; the short window improves availability without eliminating these nuisance factors.')
    replace('CSI + SNR produces','CSI + SNR produces two inputs. Adding one map produces seven; combining SNR and all maps gives 21; adding CSI gives 22. Radar descriptors summarize available frames within the minute, while CSI summarizes three-second window variances. The evaluated decision unit is a minute. A streaming three-second decision system would require a separate alignment, aggregation, and latency evaluation.')
    replace('The original chronological partitions',f'The original chronological partitions are preserved. Neither minute windows nor overlapping three-second windows are randomly distributed across training and evaluation. The primary comparison comprises {int(counts["train"])} training minutes, {int(counts["validation_minutes"])} validation minutes, and {nt} test minutes. Every configuration uses this identical cohort, so availability differences do not explain differences between input combinations.')
    replace('Balanced accuracy (BA) weights',f'Balanced accuracy (BA) weights empty specificity and occupied sensitivity equally. ROC AUC measures ranking across possible thresholds, whereas BA describes the frozen operating point. Ordinary accuracy and occupied-class F1 are also reported. The matched test contains {ne} empty and {no} occupied minutes. An always-occupied classifier gives {100*no/nt:.1f}% ordinary accuracy and 50% BA, providing a useful reference for interpreting the measured results.')
    replace('Threshold tuning and comparison','Threshold tuning and comparison of 26 candidates make validation scores optimistic. The three-second revision was motivated by the observed availability problem in the earlier long-window analysis, and these test recordings have already been inspected during project development. Although this run selects model and threshold from validation only, its test results remain exploratory. A prospectively untouched acquisition session is required for confirmation.')
    replace('The requested CSI configuration',f'The raw three-second variance feature has AUC {vauc:.3f} on validation and {tauc:.3f} on test when larger variance is treated as stronger occupancy evidence. These ranking values are distinct from a trained classifier score. Figure 2 displays the current matched test cohort, including {ne} empty and {no} occupied minutes. Overlapping distributions indicate why variance alone or an SNR proxy need not yield an error-free decision boundary.')
    replace('The radar maps also shift',f'Median minute-mean RA log power is {med["train"]:.3f} in training, {med["validation_minutes"]:.3f} in validation, and {med["test_minutes"]:.3f} in test. These observed differences describe the enlarged cohort used in this revision. The current analysis does not establish whether their cause is hardware, environment, acquisition settings, or a combination. Their effect on classifier transfer should be tested with controlled normalization experiments.')
    replace('A. CSI and simple fusion','A. Selected model and simple fusion')
    replace('CSI alone with LR is',f'The overall validation-selected candidate is {selected["features"]} ({selected["model"]}), with validation BA {selected["balanced_accuracy"]:.3f} and AUC {selected["auc"]:.3f}. At its frozen threshold of {selected["threshold"]:.6g}, test BA is {win.balanced_accuracy:.3f} and AUC is {win.auc:.3f}. Its confusion counts are TN = {int(win.tn)}, FP = {int(win.fp)}, FN = {int(win.fn)}, and TP = {int(win.tp)}. Test specificity is {100*win.tn/(win.tn+win.fp):.1f}%, sensitivity {100*win.tp/(win.tp+win.fn):.1f}%, ordinary accuracy {100*win.accuracy:.1f}%, and occupied-class F1 {win.f1:.3f}.')
    replace('Adding SNR to CSI with',f'The validation-selected CSI-only {csi.model} gives test BA {csi.balanced_accuracy:.3f} and AUC {csi.auc:.3f}. CSI + SNR ({fusion.model}) gives BA {fusion.balanced_accuracy:.3f} and AUC {fusion.auc:.3f}; SNR alone ({snr.model}) gives BA {snr.balanced_accuracy:.3f} and AUC {snr.auc:.3f}. These are same-cohort comparisons with separately validation-selected operating thresholds. They should not be conflated with a threshold optimized after observing test labels.')
    replace('CSI + SNR + RD with',f'CSI + SNR + RD ({rd.model}) gives test AUC {rd.auc:.3f} and BA {rd.balanced_accuracy:.3f}, with TN = {int(rd.tn)}, FP = {int(rd.fp)}, FN = {int(rd.fn)}, and TP = {int(rd.tp)}. Relative to the validation-selected CSI-only classifier, its BA difference is {100*(rd.balanced_accuracy-csi.balanced_accuracy):+.1f} percentage points and its AUC difference is {rd.auc-csi.auc:+.3f}. Ranking performance and the frozen operating point must be assessed separately.')
    ra,re,xy=[test(n) for n in ['CSI+SNR+RA','CSI+SNR+RE','CSI+SNR+XY']]
    replace('The validation-selected RA, RE',f'The RA, RE, and XY fusion candidates give test BA {ra.balanced_accuracy:.3f}, {re.balanced_accuracy:.3f}, and {xy.balanced_accuracy:.3f}, respectively, using their validation-selected classifiers. Full CSI-radar fusion ({allrad.model}) gives AUC {allrad.auc:.3f} and BA {allrad.balanced_accuracy:.3f}. Table II reports all input sets, avoiding selection of a preferred representation from test scores. This experiment evaluates specific pooled descriptors and classifiers; it does not establish the best achievable performance from raw radar or CSI.')
    replace('RA and XY are deterministically',f'RA and XY are deterministically related, while SNR, RD, RA, and RE all originate from the same radar. Additional feature count should not be equated with additional independent sensing evidence. The full vector has 22 inputs for {int(counts["train"])} supervised training minutes. Regularization and shallow trees limit complexity, but cannot by themselves ensure invariance to changed acquisition conditions.')
    replace('Some map-only LR candidates','Map descriptors combine static scene response and temporal change. A classifier can therefore exploit background or acquisition differences as well as occupancy-related variation. A controlled follow-up should verify decoder assumptions and acquisition settings, then compare background removal and relative-energy normalization on development data. Improvements should be tested on a new session rather than obtained through repeated selection on the current test.')
    replace('The 52 paired test minutes',f'The revised matched cohort retains {nt}/249 = {100*nt/249:.1f}% of test minutes: {ne}/96 empty and {no}/153 occupied minutes (Fig. 4). The three-second CSI feature itself is available in all 249 test minutes. This eliminates the previous long-window CSI exclusion problem. Minute-level availability only requires one valid window, however; it does not imply uninterrupted valid CSI throughout the entire minute.')
    qualified=raw[raw.split=='test_minutes'].n_windows_3s
    replace('One additional error among',f'Test minutes contain between {int(qualified.min())} and {int(qualified.max())} valid three-second windows, with median {qualified.median():.1f}. Variation in this count changes the evidence available to a minute-level median. One empty error changes specificity by {100/ne:.2f} percentage points and BA by {50/ne:.2f} points. Adjacent minutes and overlapping windows remain correlated, so independent-window confidence intervals are inappropriate. No cross-room confidence claim follows from increased coverage alone.')
    replace('The representation is designed','The representation is designed for conventional classifiers rather than a learned high-dimensional feature extractor. Once per-second statistics are available, projection uses a fixed small matrix multiplication. Each variance window computes a two-dimensional centroid and the mean squared deviations of three dots. LR inference is linear in scalar feature count. A depth-4, 200-tree RF requires at most about 800 internal decision tests per example. These structural observations do not quantify end-to-end processing speed.')
    replace('The main limitations are','The main limitations are temporal dependence, schedule-derived test annotations, previous inspection of the evaluation partition, unverified hardware metadata, and unequal numbers of valid short windows within minutes. All test minutes are now retained by the CSI feature, but coverage alone does not validate labels or establish independent evidence. Calibration is dominated by sleep, and sleep is absent from validation and test; no conclusion about sleep discrimination follows from the binary scores.')
    replace('This paper presented a reproducible',f'This paper presented a CSI-radar occupancy study using variance of three consecutive one-second observations in a fixed two-dimensional PCA space. The sum of coordinate variances replaces cumulative inter-dot distance. The revised feature is available in every labeled minute, including all 96 empty and 153 occupied test minutes. On the matched cohort, the validation-selected {selected["features"]} ({selected["model"]}) reaches {100*win.balanced_accuracy:.1f}% test BA and {win.auc:.3f} AUC; CSI alone reaches {100*csi.balanced_accuracy:.1f}% BA. The resulting baseline supports further study of radar normalization, short-window evidence, and prospective evaluation without the severe minute-exclusion bias of the earlier long-window configuration.')
    updated=[]
    for kind,value in blocks:
        if kind=='table' and value[2].startswith('TABLE I.'):
            rows=[['Partition','Raw E/S/P','CSI E/S/P','Paired E/S/P']]
            for split in ['calibration_minutes','train','validation_minutes','test_minutes']:
                data=audit[audit.split==split].set_index('activity')
                vals=['/'.join(str(int(data.loc[a,c])) for a in ['empty','sleep','present']) for c in ['raw','csi_qualified','paired']]
                if split=='calibration_minutes':vals[-1]='-'
                rows.append([split.replace('_minutes','').capitalize()]+vals)
            value=(rows,value[1],'TABLE I. Raw, three-second CSI-qualified, and fully paired minute counts. E: empty; S: sleep; P: present. Calibration is used only for PCA fitting.')
        elif kind=='fig':
            name,height,caption=value
            if name=='test_scatter.png':caption=f'Fig. 2. Matched test-minute PCA variance trace versus the radar SNR proxy, including {ne} empty and {no} occupied minutes. Variance is the median of three-second window variances; the vertical axis is logarithmic.'
            if name=='coverage.png':caption='Fig. 4. Test-minute retention by class under the revised three-second variance protocol. Inclusion requires a valid short window and all radar inputs, not uninterrupted minute-long CSI.'
            if name=='fusion_comparison.png':caption='Fig. 3. Validation and test balanced accuracy with the three-second variance feature. Each input set uses its validation-selected classifier and threshold.'
            value=(name,height,caption)
        elif isinstance(value,str):
            value=value.replace('trajectory-length statistic','projection-variance statistic').replace('overlapping CSI paths','overlapping CSI windows')
        updated.append((kind,value))
    return updated
